def find_length(s, n):
    # Convert 1s to -1 and 0s to +1, then find maximum subarray sum
    # This gives the maximum difference between number of 0s and 1s in any substring
    max_diff = 0
    current = 0
    for ch in s:
        if ch == '0':
            current += 1
        else:
            current -= 1
        if current < 0:
            current = 0
        if current > max_diff:
            max_diff = current
    return max_diff
